-- RESTBR SHORASH: guarded image / price / new-product sync, 2026-11-10
-- Backed up in private schema restbr_internal.menu_import_backups, id=1.
-- Source: public Kurdunus API, validated against current RESTBR public catalog.
-- 38 migrated images -> Shorash-owned GitHub photo repo (1 custom Pancakes photo deliberately preserved).
-- 9 added products & 9 corresponding options, 2 existing prices. Non-destructive:
-- No removals, no category moves, no badges/discounts/settings resets, no hidden item reactivation.
-- UPDATEs require exact pre-sync values; mismatch aborts and rolls back whole transaction.
begin;
set local lock_timeout = '4s';
set local statement_timeout = '45s';
do $restbr_sync$
declare
  num integer;
begin
  if not exists (select 1 from restbr_internal.menu_import_backups where id=1 and jsonb_array_length(snapshot->'products')=168 and jsonb_array_length(snapshot->'product_options')=238) then
    raise exception 'Backup id=1 not present / inconsistent, aborting sync';
  end if;
