  )
  update public.products p set image_url=input.updated_url,updated_at=now()
  from input where p.id=input.id and p.image_url=input.expected_url and p.is_active=true and p.is_visible=true;
  get diagnostics num = row_count;
  if num<>38 then raise exception 'Image preconditions changed: expected 38, updated %',num; end if;
  
  -- Exact price changes; preserve custom takeaway prices if they differ from the old dine-in price.
  with input as (
    select * from jsonb_to_recordset($restbr_json$[{"id":"9e68d1f9-5a51-5bf1-af6a-986d2f9ab38a","name":"بوكس شاورما","option_id":"6c796fea-29c8-58da-b8e7-606f567277b4","old_price":4000,"new_price":5000},{"id":"b629ed6d-287a-5dab-811b-5c412a7f1287","name":"كوكتيل موز حليب","option_id":"5ddf261f-dd37-56c1-81c6-75b149b91363","old_price":6000,"new_price":5000}]$restbr_json$::jsonb) as x(id uuid, name text, option_id uuid, old_price numeric, new_price numeric)
  )
  update public.product_options o
    set price=i.new_price,
        takeaway_price=case when o.takeaway_price=i.old_price then i.new_price else o.takeaway_price end,
        updated_at=now()
  from input i where o.id=i.option_id and o.product_id=i.id and o.price=i.old_price;
  get diagnostics num=row_count;
  if num<>2 then raise exception 'Option prices changed since snapshot: expected 2, updated %',num; end if;
  
