    select * from jsonb_to_recordset($restbr_json$[{"id":"9e68d1f9-5a51-5bf1-af6a-986d2f9ab38a","name":"بوكس شاورما","option_id":"6c796fea-29c8-58da-b8e7-606f567277b4","old_price":4000,"new_price":5000},{"id":"b629ed6d-287a-5dab-811b-5c412a7f1287","name":"كوكتيل موز حليب","option_id":"5ddf261f-dd37-56c1-81c6-75b149b91363","old_price":6000,"new_price":5000}]$restbr_json$::jsonb) as x(id uuid,name text, option_id uuid,old_price numeric,new_price numeric)
  )
  update public.products p set base_price=i.new_price,updated_at=now()
  from input i where p.id=i.id and p.name_ar=i.name and p.base_price=i.old_price;
  get diagnostics num=row_count;
  if num<>2 then raise exception 'Product base prices changed since snapshot: expected 2, updated %',num; end if;

  -- Add new externally documented products only in existing categories, with deterministic IDs for idempotence.
  with input as (
