       md5('restbr-kurdunus-20261110-product-'||i.external_id)::uuid,
       i.name_ar,i.name_ku,i.name_en,i.price,i.price,i.ord,true,true
  from input i;
  get diagnostics num=row_count;
  if num<>9 then raise exception 'New option mismatch: expected 9, inserted %',num; end if;
end
